function raw16(string $body,array $headers=[],int $status=200): string {$out='HTTP/1.1 '.$status." OK\r\n";foreach($headers as $k=>$v){$out.=$k.': '.$v."\r\n";}if(!isset($headers['Content-Length'])){$out.='Content-Length: '.strlen($body)."\r\n";}return $out."\r\n".$body;}
