function gatewaySale16(string $currency='CNY'): array {return ['sale_no'=>'CY202600001','remote_id'=>'cs_fixture','trade_no'=>'trade_fixture','amount'=>1200,'currency'=>$currency,'expires_at'=>time()+3600,'return_url'=>'https://island.example.com/index.php?r=receipt','notify_url'=>'https://island.example.com/notify-direct.php','payer_ip'=>'8.8.8.8'];}
test('016 Stripe exact binding, mode, amount and currency verification',static function(){$sale=gatewaySale16();$response=['id'=>'cs_fixture','mode'=>'payment','client_reference_id'=>$sale['sale_no'],'livemode'=>false,'payment_status'=>'paid','payment_intent'=>'pi_fixture','amount_total'=>1200,'currency'=>'cny'];foreach(['valid','mode','currency','amount','live','reference'] as $case){$body=$response;if($case==='mode'){$body['mode']='subscription';}if($case==='currency'){$body['currency']='usd';}if($case==='amount'){$body['amount_total']=1;}if($case==='live'){$body['livemode']=true;}if($case==='reference'){$body['client_reference_id']='other';}$driver=new \Chengyu\Payments\Stripe(['stripe_secret'=>'sk_test_fixture'],new HttpClient(static function()use($body){return response15($body);}));if($case==='valid'){same('paid',$driver->query($sale)['state']);}else{reject(static function()use($driver,$sale){$driver->query($sale);},409);}}});
test('016 Stripe HMAC rejects replay age and modified bytes',static function(){$driver=new \Chengyu\Payments\Stripe(['stripe_webhook_secret'=>'whsec_fixture'],new HttpClient());$raw=json_encode(['type'=>'checkout.session.completed','data'=>['object'=>['id'=>'cs_fixture']]]);$time=time();$sig=hash_hmac('sha256',$time.'.'.$raw,'whsec_fixture');same('cs_fixture',$driver->notification($raw,['stripe-signature'=>'t='.$time.',v1='.$sig]));reject(static function()use($driver,$raw,$time,$sig){$driver->notification($raw.' ',['stripe-signature'=>'t='.$time.',v1='.$sig]);},403);$old=$time-400;reject(static function()use($driver,$raw,$old){$driver->notification($raw,['stripe-signature'=>'t='.$old.',v1='.hash_hmac('sha256',$old.'.'.$raw,'whsec_fixture')]);},403);});
