test('016 Alipay RSA2 signs requests and verifies exact original response bytes',static function()use($private16,$public16){$sale=gatewaySale16();$c=['alipay_direct_sandbox'=>true,'alipay_direct_appid'=>'fixtureapp','alipay_direct_seller'=>'fixtureseller','alipay_direct_private'=>$private16,'alipay_direct_public'=>$public16];$driver=new \Chengyu\Payments\Alipay($c,new HttpClient(static function($method,$url,$headers,$body)use($private16,$public16,$sale){parse_str($body,$fields);$sig=$fields['sign'];unset($fields['sign']);ksort($fields);$pairs=[];foreach($fields as $k=>$v){$pairs[]=$k.'='.$v;}\Chengyu\Payments\Tools::rsaVerify(implode('&',$pairs),$sig,$public16);$r=json_encode(['code'=>'10000','out_trade_no'=>$sale['sale_no'],'trade_no'=>'ali_trade','total_amount'=>'12.00','trade_status'=>'TRADE_SUCCESS']);return raw16('{"alipay_trade_query_response":'.$r.',"sign":'.json_encode(\Chengyu\Payments\Tools::rsaSign($r,$private16)).'}');}));same('ali_trade',$driver->query($sale)['trade']);$notify=['app_id'=>'fixtureapp','seller_id'=>'fixtureseller','out_trade_no'=>$sale['sale_no'],'sign_type'=>'RSA2'];$notify['sign']=\Chengyu\Payments\Tools::rsaSign(\Chengyu\Payments\Alipay::canonical($notify),$private16);same($sale['sale_no'],$driver->notification(http_build_query($notify),[]));$notify['seller_id']='other';reject(static function()use($driver,$notify){$driver->notification(http_build_query($notify),[]);},403);});
