test('016 WeChat RSA response binds merchant, app, timestamp and platform serial',static function()use($private16,$public16){$c=['wechat_mchid'=>'merchant1','wechat_appid'=>'app1','wechat_serial'=>'MERCHANTSERIAL','wechat_private'=>$private16,'wechat_platform_serial'=>'PLATFORMSERIAL','wechat_platform_public'=>$public16];$sale=gatewaySale16();$driver=new \Chengyu\Payments\Wechat($c,new HttpClient(static function($method,$url,$headers,$body)use($private16,$sale){truth(strpos($headers['Authorization'],'WECHATPAY2-SHA256-RSA2048')===0);$raw=json_encode(['mchid'=>'merchant1','appid'=>'app1','out_trade_no'=>$sale['sale_no'],'trade_state'=>'SUCCESS','transaction_id'=>'wxtrade','amount'=>['total'=>1200,'currency'=>'CNY']]);$t=(string)time();$nonce='fixture';return raw16($raw,['Wechatpay-Timestamp'=>$t,'Wechatpay-Nonce'=>$nonce,'Wechatpay-Serial'=>'PLATFORMSERIAL','Wechatpay-Signature'=>\Chengyu\Payments\Tools::rsaSign($t."\n".$nonce."\n".$raw."\n",$private16)]);}));same('wxtrade',$driver->query($sale)['trade']);reject(static function()use($driver){$driver->verify('{}',['wechatpay-timestamp'=>(string)time(),'wechatpay-nonce'=>'n','wechatpay-serial'=>'UNKNOWN']);},403);});
test('016 PayPal active capture validates merchant and amount before fulfillment',static function(){$sale=gatewaySale16('USD');$sale['remote_id']='PAYPALORDER';$c=['paypal_sandbox'=>true,'paypal_id'=>'client','paypal_secret'=>'secret','paypal_merchant'=>'merchant'];$driver=new \Chengyu\Payments\PayPal($c,new HttpClient(static function($method,$url,$headers,$body)use($sale){if(strpos($url,'oauth2/token')!==false){return response15(['access_token'=>'token','expires_in'=>300]);}$unit=['reference_id'=>$sale['sale_no'],'payee'=>['merchant_id'=>'merchant'],'amount'=>['currency_code'=>'USD','value'=>'12.00']];if($method==='POST'){same('capture-'.$sale['sale_no'],$headers['PayPal-Request-Id']);$unit['payments']=['captures'=>[['id'=>'CAPTURE','status'=>'COMPLETED','amount'=>['value'=>'12.00','currency_code'=>'USD']]]];}return response15(['id'=>'PAYPALORDER','status'=>$method==='POST'?'COMPLETED':'APPROVED','purchase_units'=>[$unit]]);}));same('CAPTURE',$driver->query($sale)['trade']);});

test('016 object lifecycle uses conditional immutable copy, recovers a lost response and returns one media ID',static function()use($a,$admin){
    $saved=[];foreach(['object_storage_enabled','s3_endpoint','s3_region','s3_access','s3_secret','s3_bucket','s3_prefix'] as $key){$saved[$key]=$a->settings->get($key);}
    $cfg=s3config16();$seed=['object_storage_enabled'=>true];foreach(['endpoint','region','access','secret','bucket','prefix'] as $key){$seed['s3_'.$key]=$cfg[$key];}settings('media_plus',$seed);
    try{
        $data='A private object lifecycle fixture.';$etag='"fixture-etag"';$manifest=null;$copied=false;$copyCount=0;$loseResponse=true;
        $http=new HttpClient(static function($method,$url,$headers,$body)use(&$manifest,$data,$etag,&$copied,&$copyCount,&$loseResponse){
            $isFinal=strpos($url,'/media/')!==false;
            $head=['Content-Type'=>'text/plain','Content-Length'=>(string)strlen($data),'ETag'=>$etag,'x-amz-meta-cy-id'=>$manifest['upload_key']];
            if($isFinal){$head['x-amz-meta-cy-source']=hash('sha256',$etag);}
            if($method==='HEAD'){if($isFinal&&!$copied){return raw16('',[],404);}return raw16('',$head);}
            if($method==='GET'){same($etag,$headers['if-match']);return raw16($data,$head,206);}
            same('PUT',$method);same($etag,$headers['x-amz-copy-source-if-match']);truth(strpos($headers['x-amz-copy-source'],'/staging/'.$manifest['upload_key'])!==false);
            $copied=true;$copyCount++;
            if($loseResponse){$loseResponse=false;throw new \Chengyu\Core\Problem('Fixture: copy response lost.',502);}
            return raw16('<CopyObjectResult><ETag>"copied"</ETag></CopyObjectResult>');
        });
        $objects=new \Chengyu\Services\ObjectStorage($a,$http);$u=account($admin);$manifest=$objects->prepare($u,'private.txt',strlen($data));
        truth(strpos($manifest['url'],'/staging/')!==false);truth(strpos($manifest['url'],'content-length')!==false);truth(!isset($manifest['headers']['content-length']));
        reject(static function()use($objects,$u,$manifest){$objects->finish($u,$manifest['upload_key']);},502);
        $id=$objects->finish($u,$manifest['upload_key']);same($id,$objects->finish($u,$manifest['upload_key']));same(1,$copyCount);
        $media=$a->db->one('SELECT * FROM cy_media WHERE id=?',[$id]);same('s3',$media['backend']);same(1,(int)$media['is_private']);
        $url=$objects->download($media);truth(strpos($url,'/media/')!==false);truth(strpos($url,'/staging/')===false);truth(strpos($url,'X-Amz-Expires=120')!==false);
        reject(static function()use($a,$id){$a->media->readable($id,null);},403);
    }finally{foreach($saved as $key=>$value){if($value===''&&($a->settings->schema()[$key][2]??'')==='secret'){$saved['clear_'.$key]='1';}}settings('media_plus',$saved);}
});
test('016 future schema version is rejected before older code can write data',static function()use($a){
    $a->db->execute('UPDATE cy_settings SET value=? WHERE name=?',[(string)(\Chengyu\Core\Migrations::VERSION+1),'_schema_version']);
    try{reject(static function()use($a){\Chengyu\Core\Migrations::upgrade($a->db,$a->config['storage']);},503);}finally{$a->db->execute('UPDATE cy_settings SET value=? WHERE name=?',[(string)\Chengyu\Core\Migrations::VERSION,'_schema_version']);}
});
